// Compliance: la nota de voz del cliente y el audio generado solo viven en la memoria
// de esta ejecución. Aquí se descartan los binarios y se conserva solo metadata no sensible.
return $input.all().map(item => ({
  json: {
    canal: 'telegram',
    estado: 'audio_enviado',
    binarios_eliminados: Object.keys(item.binary ?? {}).length,
    audio_almacenado: false,
    fecha: $now.toISO()
  }
}));

